# MATLAB Program to Convert Ultrasound Signal to Frequency Domain

Here's a comprehensive program to convert an ultrasound signal from voltage vs time to magnitude (dB) vs frequency:

```matlab
%% Ultrasound Signal Processing - Time to Frequency Domain Conversion
% Converts voltage vs time to magnitude (dB) vs frequency (MHz)
% Author: Signal Processing
% Date: 2024

clear all; close all; clc;

%% ===== 1. GENERATE OR LOAD ULTRASOUND SIGNAL =====

% Option A: Generate synthetic ultrasound signal
% Parameters
fs = 100e6;                    % Sampling frequency (100 MHz)
duration = 10e-6;             % Duration (10 microseconds)
t = 0:1/fs:duration-1/fs;    % Time vector
t_us = t * 1e6;              % Time in microseconds for plotting

% Create ultrasound signal (example: 5 MHz carrier with Gaussian envelope)
f_center = 5e6;               % Center frequency (5 MHz)
bandwidth = 1e6;              % Bandwidth (1 MHz)
sigma = 2e-6;                 % Gaussian envelope width

% Ultrasound signal
voltage = exp(-(t - duration/2).^2 / (2*sigma^2)) .* ...
          sin(2*pi*f_center*t) + ...
          0.1*randn(size(t));  % Add 10% noise

% Option B: Load your own signal from file
% load('ultrasound_signal.mat');  % Load data containing: t, voltage

%% ===== 2. TIME DOMAIN PLOT =====

figure('Position', [100 100 1200 800]);

subplot(3,2,1);
plot(t_us, voltage, 'b', 'LineWidth', 1.5);
xlabel('Time (µs)', 'FontSize', 11);
ylabel('Voltage (V)', 'FontSize', 11);
title('Ultrasound Signal - Time Domain', 'FontSize', 12, 'FontWeight', 'bold');
grid on;
xlim([min(t_us) max(t_us)]);

subplot(3,2,2);
plot(t_us, voltage, 'b', 'LineWidth', 1.5);
xlabel('Time (µs)', 'FontSize', 11);
ylabel('Voltage (V)', 'FontSize', 11);
title('Ultrasound Signal - Zoomed View', 'FontSize', 12, 'FontWeight', 'bold');
grid on;
xlim([2 3]);  % Zoom to 1 µs window

%% ===== 3. APPLY WINDOW FUNCTION =====

% Window options: 'hamming', 'hann', 'blackman', 'rectangular'
window_type = 'hamming';
window = getwindow(window_type, length(voltage))';

subplot(3,2,3);
plot(t_us, window, 'r', 'LineWidth', 1.5);
xlabel('Time (µs)', 'FontSize', 11);
ylabel('Window Amplitude', 'FontSize', 11);
title(sprintf('%s Window', upper(window_type)), 'FontSize', 12, 'FontWeight', 'bold');
grid on;

% Apply window to signal
voltage_windowed = voltage .* window;

%% ===== 4. COMPUTE FFT =====

N = length(voltage_windowed);     % Number of samples
fft_result = fft(voltage_windowed, N);  % Compute FFT
magnitude_linear = abs(fft_result) / (N/2);  % Normalize magnitude

% Single-sided spectrum
magnitude_ss = magnitude_linear(1:N/2+1);
magnitude_ss(2:end-1) = 2*magnitude_ss(2:end-1);

% Convert to dB
magnitude_dB = 20*log10(magnitude_ss + eps);  % Add eps to avoid log(0)

% Frequency vector
freq = linspace(0, fs/2, length(magnitude_ss));
freq_MHz = freq / 1e6;  % Convert to MHz

%% ===== 5. FREQUENCY DOMAIN PLOTS =====

% Linear magnitude vs frequency
subplot(3,2,4);
plot(freq_MHz, magnitude_ss, 'b', 'LineWidth', 1.5);
xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (V)', 'FontSize', 11);
title('FFT - Linear Magnitude vs Frequency', 'FontSize', 12, 'FontWeight', 'bold');
grid on;
xlim([0 20]);

% dB magnitude vs frequency (full range)
subplot(3,2,5);
plot(freq_MHz, magnitude_dB, 'b', 'LineWidth', 1.5);
xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (dB)', 'FontSize', 11);
title('FFT - Magnitude (dB) vs Frequency', 'FontSize', 12, 'FontWeight', 'bold');
grid on;
xlim([0 20]);
ylim([min(magnitude_dB)-10 max(magnitude_dB)+5]);

% dB magnitude vs frequency (zoomed - dynamic range)
subplot(3,2,6);
plot(freq_MHz, magnitude_dB, 'b', 'LineWidth', 1.5);
xlabel('Frequency (MHz)', 'FontSize', 11);
ylabel('Magnitude (dB)', 'FontSize', 11);
title('FFT - Magnitude (dB) vs Frequency (Zoomed)', 'FontSize', 12, 'FontWeight', 'bold');
grid on;
xlim([0 20]);
ylim([max(magnitude_dB)-60 max(magnitude_dB)+5]);  % 60 dB dynamic range

%% ===== 6. EXTRACT KEY PARAMETERS =====

% Find peak frequency
[peak_mag_dB, peak_idx] = max(magnitude_dB);
peak_freq_MHz = freq_MHz(peak_idx);

% -3dB bandwidth
threshold_3dB = peak_mag_dB - 3;
idx_3dB = find(magnitude_dB >= threshold_3dB);
f_low_3dB = freq_MHz(min(idx_3dB));
f_high_3dB = freq_MHz(max(idx_3dB));
bandwidth_3dB = f_high_3dB - f_low_3dB;

% -6dB bandwidth
threshold_6dB = peak_mag_dB - 6;
idx_6dB = find(magnitude_dB >= threshold_6dB);
f_low_6dB = freq_MHz(min(idx_6dB));
f_high_6dB = freq_MHz(max(idx_6dB));
bandwidth_6dB = f_high_6dB - f_low_6dB;

%% ===== 7. DISPLAY RESULTS =====

fprintf('\n========== ULTRASOUND SIGNAL ANALYSIS ==========\n');
fprintf('Sampling Frequency: %.1f MHz\n', fs/1e6);
fprintf('Signal Duration: %.2f µs\n', duration*1e6);
fprintf('Number of Samples: %d\n', N);
fprintf('Frequency Resolution: %.4f MHz\n', (fs/N)/1e6);
fprintf('\n---------- Spectral Characteristics ----------\n');
fprintf('Peak Frequency: %.4f MHz\n', peak_freq_MHz);
fprintf('Peak Magnitude: %.2f dB\n', peak_mag_dB);
fprintf('-3dB Bandwidth: %.4f MHz (%.4f - %.4f MHz)\n', bandwidth_3dB, f_low_3dB, f_high_3dB);
fprintf('-6dB Bandwidth: %.4f MHz (%.4f - %.4f MHz)\n', bandwidth_6dB, f_low_6dB, f_high_6dB);
fprintf('================================================\n\n');

%% ===== 8. SAVE RESULTS =====

% Create output table
results_table = table(...
    peak_freq_MHz, ...
    peak_mag_dB, ...
    bandwidth_3dB, ...
    bandwidth_6dB, ...
    'VariableNames', {'Peak_Freq_MHz', 'Peak_Mag_dB', 'BW_3dB_MHz', 'BW_6dB_MHz'});

disp(results_table);

% Save frequency domain data
output_data = table(freq_MHz', magnitude_ss', magnitude_dB', ...
    'VariableNames', {'Frequency_MHz', 'Magnitude_Linear', 'Magnitude_dB'});

% Uncomment to save to file
% writetable(output_data, 'ultrasound_fft_results.csv');
% save('ultrasound_fft_results.mat', 'freq_MHz', 'magnitude_dB', 'magnitude_ss');

%% ===== 9. ADDITIONAL ANALYSIS - POWER SPECTRAL DENSITY =====

figure;
% Welch's method for PSD estimation (more robust)
[pxx, f_welch] = pwelch(voltage_windowed, [], [], [], fs);
f_welch_MHz = f_welch / 1e6;
pxx_dB = 10*log10(pxx + eps);

plot(f_welch_MHz, pxx_dB, 'b', 'LineWidth', 1.5);
xlabel('Frequency (MHz)', 'FontSize', 12);
ylabel('Power Spectral Density (dB/Hz)', 'FontSize', 12);
title('Power Spectral Density - Welch Method', 'FontSize', 13, 'FontWeight', 'bold');
grid on;
xlim([0 20]);

%% ===== HELPER FUNCTION =====

function window = getwindow(window_type, N)
    % Create window function
    switch lower(window_type)
        case 'hamming'
            window = hamming(N);
        case 'hann'
            window = hann(N);
        case 'blackman'
            window = blackman(N);
        case 'rectangular'
            window = ones(N, 1);
        otherwise
            warning('Unknown window type. Using Hamming window.');
            window = hamming(N);
    end
end
```

